"""Read and update separate local notes for individual multi-step tasks."""

import re
import uuid
from pathlib import Path

from config import get_app_data_dir

# Store all notes in one fixed directory; each tool-created task ID maps to one file.
SCRATCHPAD_DIR = get_app_data_dir() / "task_scratchpads"
# IDs are generated by this tool and validated before they are used in a filename.
TASK_ID_PATTERN = re.compile(r"^[a-f0-9]{32}$")
# Bound note size to prevent the model from filling local storage or bloating future context.
MAX_CONTENT_LENGTH = 12_000

# The model can create a task ID, then read, replace, or clear only that task's note.
DECLARATION = {
    "type": "function",
    "name": "task_scratchpad",
    "description": (
        "Manage a separate local scratchpad for each substantial multi-step task. "
        "First call action=create to receive a unique task_id. Reuse that exact task_id "
        "for read, write, and clear calls for this task; do not invent or change the ID. "
        "write replaces the whole note. Keep notes concise and never store secrets. "
        "Do not use for simple questions or unrelated persistent memory."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "action": {"type": "string", "enum": ["create", "read", "write", "clear"]},
            "task_id": {
                "type": "string",
                "description": "ID returned by create; required for read, write, and clear.",
            },
            "content": {"type": "string", "description": "Complete concise note for write; omit for read/clear."},
        },
        "required": ["action"],
    },
}

LIVE_DECLARATION = {key: value for key, value in DECLARATION.items() if key != "type"}


def task_scratchpad(action: str, task_id: str = "", content: str = "") -> dict:
    """Create or manage a task-specific note and return a structured result.

    ``create`` allocates an unpredictable UUID and an empty note file. Later
    actions require that returned ID, which is validated before forming a path.
    ``write`` replaces the full note, with a size limit and a basic secret-marker
    check. This is a convenience check, not a complete secret detector.
    """
    if action == "create":
        try:
            SCRATCHPAD_DIR.mkdir(parents=True, exist_ok=True)
            # Exclusive creation handles even the extremely unlikely case of an ID collision.
            while True:
                new_task_id = uuid.uuid4().hex
                task_file = SCRATCHPAD_DIR / f"{new_task_id}.txt"
                try:
                    with task_file.open("x", encoding="utf-8"):
                        pass
                    return {
                        "success": True,
                        "task_id": new_task_id,
                        "message": "Task scratchpad created.",
                    }
                except FileExistsError:
                    continue
        except OSError as exc:
            return {"success": False, "error": str(exc)}

    if action not in {"read", "write", "clear"}:
        return {"success": False, "error": "Action must be create, read, write, or clear."}
    if not isinstance(task_id, str) or not TASK_ID_PATTERN.fullmatch(task_id):
        return {
            "success": False,
            "error": "Provide the 32-character task_id returned by the create action.",
        }

    task_file = SCRATCHPAD_DIR / f"{task_id}.txt"
    if action == "read":
        try:
            return {"success": True, "task_id": task_id,
                    "content": task_file.read_text(encoding="utf-8")}
        except FileNotFoundError:
            return {"success": False, "error": "No scratchpad exists for this task_id."}
        except OSError as exc:
            return {"success": False, "error": str(exc)}

    if action == "clear":
        try:
            # missing_ok makes cleanup safe to repeat after an interrupted task.
            task_file.unlink(missing_ok=True)
            return {"success": True, "task_id": task_id,
                    "message": "Task scratchpad cleared."}
        except OSError as exc:
            return {"success": False, "error": str(exc)}

    # Validate size and type before touching the existing note.
    if not isinstance(content, str) or len(content) > MAX_CONTENT_LENGTH:
        return {"success": False, "error": f"Scratchpad content must be at most {MAX_CONTENT_LENGTH} characters."}
    if any(marker in content.casefold() for marker in ("api_key=", "api key:", "password=")):
        return {"success": False, "error": "Do not store credentials or secrets in the scratchpad."}
    try:
        if not task_file.is_file():
            return {"success": False, "error": "No scratchpad exists for this task_id; create one first."}
        # Replace through a unique temporary file so interrupted or concurrent writes do not mix notes.
        temporary = task_file.with_suffix(f".{uuid.uuid4().hex}.tmp")
        temporary.write_text(content, encoding="utf-8")
        temporary.replace(task_file)
        return {"success": True, "task_id": task_id,
                "message": "Task scratchpad updated."}
    except OSError as exc:
        return {"success": False, "error": str(exc)}
